        for (int j = 0; j < n; j++) res[j][n - 1 - i] = g[i][j];
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) cout << res[i][j] << (j + 1 < n ? " " : "\n");
